css:
.tc{position:absolute;left:16px;top:16px;width:328px;height:88px;box-sizing:border-box;padding:16px;background-color:#1C1C1C;border:1px solid #F59E0B;border-radius:12px;font-family:Inter, Roboto, sans-serif}
.tc [data-part=dot]{position:absolute;left:16px;top:16px;width:8px;height:8px;border-radius:50%}
.tc [data-part=name]{position:absolute;left:32px;top:10px;color:#F8F9FA;font-size:15px;font-weight:700;letter-spacing:1px;white-space:nowrap}
.tc [data-part=tier]{position:absolute;left:16px;top:44px;color:#8A8D93;font-family:"Roboto Mono", monospace;font-size:12px;white-space:nowrap}
.tc [data-part=dot]{background-color:#F59E0B}
.tc [data-part=glow]{position:absolute;left:-1px;top:-1px;width:328px;height:88px;border-radius:12px;box-shadow:0 0 16px rgba(245,158,11,.55);animation:breathe 1200ms ease-in-out infinite alternate}
@keyframes breathe{from{opacity:.25}to{opacity:1}}
.tc [data-part=countdown]{position:absolute;right:16px;top:30px;color:#F59E0B;font-family:"Roboto Mono", monospace;font-size:15px;font-weight:500}
